er-model-keys.codeOrDiagram:
Super Key ⊃ Candidate Key ⊃ Primary Key

Example Table: Students(RollNo, Email, Phone, Name)
- Super Keys: {RollNo}, {Email}, {RollNo, Name}, {Email, Phone}
- Candidate Keys: {RollNo}, {Email}
- Primary Key: {RollNo}
- Foreign Key in Enrollments: (student_roll_no) REFERENCES Students(RollNo)

synchronization.codeOrDiagram:
Semaphore Operations (Atomic):
wait(S) {
  while (S <= 0); // or block thread
  S--;
}
signal(S) {
  S++; // and unblock waiting thread
}

caching-redis.codeOrDiagram:
async function getCachedUser(userId) {
  const cached = await redis.get(`user:${userId}`);
  if (cached) return JSON.parse(cached);
  const user = await db.users.findById(userId);
  await redis.set(`user:${userId}`, JSON.stringify(user), 'EX', 3600);
  return user;
}
